// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;

    function setUp() public {
        c = new PhiNFT1155();
    }

    function testFuzz_property(address newOwner) public {
        // admissible: the pending owner must be a real, nonzero address
        vm.assume(newOwner != address(0));

        // current owner is the zero address (never initialized), so a call from
        // address(0) passes the onlyOwner check and starts the 2-step transfer
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // the designated pending owner accepts ownership
        vm.prank(newOwner);
        c.acceptOwnership();

        // General rule: after a successful two-step ownership transfer to any
        // nonzero address, owner() reports exactly that address.
        assertTrue(c.owner() == newOwner);
    }
}
